export function PersistedState({
  storageKey = "{{storageKey}}",
  value = "{{value}}",
  storageType = "{{storageType}}",
  accent = "{{accent}}",
}) {
  const acrossSessions = storageType === "localStorage";
  const withinTab = storageType === "localStorage" || storageType === "sessionStorage";
  const cell = (ok) => <strong style={{ fontSize: 11, color: ok ? accent : "#241430" }}>{ok ? "survives" : "lost"}</strong>;
  return (
    <div style={{ font: "12px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <code style={{ display: "block", fontFamily: "ui-monospace, monospace", fontSize: 11, background: "#24143012", padding: "8px 10px", borderRadius: 6, marginBottom: 12, wordBreak: "break-all" }}>{storageType}.setItem("{storageKey}", "{value}")</code>
      <p style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "6px 0", borderBottom: "1px solid #24143014" }}><span>closes tab, reopens later</span>{cell(acrossSessions)}</p>
      <p style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "6px 0" }}><span>closes this tab only</span>{cell(withinTab)}</p>
    </div>
  );
}
